{
  "title": "ProductStatus",
  "type": "object",
  "description": "A representation of the status health of a request type. Auth requests, Balance requests, Identity requests, Transactions updates, Investments updates, and Item logins each have their own status object.",
  "properties": {
    "status": {
      "type": "string",
      "enum": [
        "HEALTHY",
        "DEGRADED",
        "DOWN"
      ],
      "description": "`HEALTHY`: the majority of requests are successful\n`DEGRADED`: only some requests are successful\n`DOWN`: all requests are failing"
    },
    "last_status_change": {
      "type": "string",
      "description": "ISO 8601 formatted timestamp of the last status change for the institution."
    },
    "breakdown": {
      "title": "StatusBreakdown",
      "type": "object",
      "description": "A detailed breakdown of the institution's performance for a request type. The values for `success`, `error_plaid`, and `error_institution` sum to 1.",
      "properties": {
        "success": {
          "description": "The percentage of login attempts that are successful, expressed as a decimal.",
          "type": "number"
        },
        "error_plaid": {
          "description": "The percentage of logins that are failing due to an internal Plaid issue, expressed as a decimal.\n",
          "type": "number"
        },
        "error_institution": {
          "description": "The percentage of logins that are failing due to an issue in the institution's system, expressed as a decimal.",
          "type": "number"
        },
        "refresh_interval": {
          "type": "string",
          "enum": [
            "NORMAL",
            "DELAYED",
            "STOPPED"
          ],
          "description": "The `refresh_interval` may be `DELAYED` or `STOPPED` even when the success rate is high. This value is only returned for Transactions status breakdowns.",
          "nullable": true
        }
      },
      "required": [
        "success",
        "error_plaid",
        "error_institution"
      ]
    }
  },
  "required": [
    "status",
    "last_status_change",
    "breakdown"
  ]
}

