{
  "title": "Account",
  "type": "object",
  "description": "A single account at a financial institution.",
  "properties": {
    "account_id": {
      "type": "string",
      "description": "Plaid’s unique identifier for the account. This value will not change unless Plaid can't reconcile the account with the data returned by the financial institution. This may occur, for example, when the name of the account changes. If this happens a new `account_id` will be assigned to the account.\n\nThe `account_id` can also change if the `access_token` is deleted and the same credentials that were used to generate that `access_token` are used to generate a new `access_token` on a later date. In that case, the new `account_id` will be different from the old `account_id`.\n\nLike all Plaid identifiers, the `account_id` is case sensitive."
    },
    "balances": {
      "$ref": "#/components/schemas/AccountBalance"
    },
